create table wksp_dtesc.sgt_equipos (
    id               number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    unidad_encargada varchar2(50 byte),
    rack_id          number not null enable,
    u                number,
    tipo_red         varchar2(50 byte) not null enable,
    nombre           varchar2(60 byte),
    tipo_equipo_id   number not null enable,
    marca            varchar2(50 byte),
    modelo           varchar2(255 byte),
    estado           varchar2(50 byte) default 'Planificado' not null enable,
    observaciones    varchar2(4000 byte),
    ni_ande          varchar2(50 byte),
    serial_number    varchar2(50 byte),
    version_hardware varchar2(50 byte),
    version_software varchar2(50 byte),
    version_patch    varchar2(50 byte),
    ip_gestion       varchar2(50 byte),
    alimentacion1_id varchar2(50 byte),
    alimentacion2_id varchar2(255 byte),
    proyecto_id      varchar2(50 byte),
    fecha_imple      date,
    altura_u         number not null enable,
    posicion         char(20 byte),
    sitio_id         number,
    creado_por       varchar2(255 byte),
    creado_el        timestamp(6),
    actualizado_por  varchar2(255 byte),
    actualizado_el   timestamp(6)
);

alter table wksp_dtesc.sgt_equipos
    add constraint chk_estados_values
        check ( estado in ( 'Utilizado', 'No utilizado / Apagado', 'Desconocido', 'Baja', 'Planificado' ) ) enable;

alter table wksp_dtesc.sgt_equipos
    add constraint chk_posicion_values
        check ( posicion in ( 'FRONT', 'BACK' ) ) enable;

alter table wksp_dtesc.sgt_equipos add primary key ( id )
    using index enable;


